using JugaadVision.Core.Enums;

namespace JugaadVision.Core.Models;

/// <summary>
/// An asset in the library (spec §4.1) — either generated by the app or imported from disk.
/// </summary>
public sealed class LibraryItem
{
    public Guid Id { get; set; } = Guid.NewGuid();

    public string Name { get; set; } = string.Empty;

    public AssetKind Kind { get; set; } = AssetKind.Unknown;

    /// <summary>Absolute path to the asset on disk. The database stores the reference, not the bytes.</summary>
    public string FilePath { get; set; } = string.Empty;

    public long SizeBytes { get; set; }

    /// <summary>Image dimensions, when the asset is an image. Null otherwise.</summary>
    public int? Width { get; set; }

    public int? Height { get; set; }

    /// <summary>Generation that produced this asset, when it was generated rather than imported.</summary>
    public Guid? GenerationId { get; set; }

    /// <summary>Project this asset belongs to, when it was saved into one.</summary>
    public Guid? ProjectId { get; set; }

    /// <summary>User tags for filtering.</summary>
    public List<string> Tags { get; set; } = [];

    public bool IsFavorite { get; set; }

    public DateTimeOffset CreatedAt { get; set; } = DateTimeOffset.UtcNow;

    public DateTimeOffset LastViewedAt { get; set; } = DateTimeOffset.UtcNow;
}
